import tools.jackson.databind.node.ObjectNode;

/** household-duplicate: Reject creating an owner when another owner has the same lastName and the same address (co... */
class AcceptanceTest extends AcceptanceBase {

	@Test
	void coreRejectsSameLastNameAndAddress() throws Exception {
		ObjectNode a = ownerNode();
		createOwnerOk(a);
